function highPathForRealm(realm){return Object.entries(HIGH_REALM_PATHS).find(([,d])=>d.fromRealm===realm);}
function highSiteNear(s,p,path,kind){const pos=p.position;if(!pos||pos.sceneId!==path.sceneId||p.location?.kind==='travel'||p.journey?.status==='traveling')return false;const site=kind==='high-chapter'?{x:43,y:34,width:6,height:5}:{x:22,y:35,width:5,height:4};return Math.hypot(Math.max(0,Math.abs(pos.x-site.x)-site.width/2),Math.max(0,Math.abs(pos.y-site.y)-site.height/2))<=2.6;}
export function acquireHighRealmChapter(s,realmId){initCultivation(s);const d=HIGH_REALM_PATHS[realmId];if(!d||!s.story.completed||s.master.realm<10)throw Error('高阶续篇需先完成云岫篇章，筑基后到真实来源查验。');if(s.srCultivation.highChapters[realmId])throw Error('此可靠续篇已实际研习，不重复领知识。');if(!highSiteNear(s,s.master,d,'high-chapter'))throw Error('须亲自走近对应航港的封存实录。');return startOrder(s,'high-chapter',{realmId},d.chapterCost,100);}
export function acquireHighRealmMaterial(s,realmId){initCultivation(s);const d=HIGH_REALM_PATHS[realmId];if(!d||!s.story.completed||s.master.realm<10)throw Error('高阶材料需先完成云岫篇章并实际查验来源。');if(!s.srCultivation.highChapters[realmId])throw Error('先实际研习该境可靠续篇，得知材料用途。');if(!highSiteNear(s,s.master,d,'high-material'))throw Error('须亲自到对应港口的有限灵材登记处。');const source=s.srCultivation.highMaterialSources[realmId];if(source.remaining<1)throw Error('此来源两份实物已取尽，不能刷新无限生成。');const r=startOrder(s,'high-material',{realmId},d.materialCost,100);source.remaining--;s.srCultivation.orders[r.orderId].materialSourceReserved=true;return r;}
export function chapterKnown(s,personId,realmId){return !!s.personsById[personId]?.highChapters?.[realmId]||personId==='person:master'&&!!s.srCultivation.highChapters?.[realmId];}
function shareNear(s,a,b){const x=a.position,y=b.position;return isLivingPerson(a)&&isLivingPerson(b)&&x?.sceneId===y?.sceneId&&Number.isFinite(x?.x)&&Number.isFinite(y?.x)&&Math.hypot(x.x-y.x,x.y-y.y)<=2.6&&a.location?.kind!=='travel'&&b.location?.kind!=='travel';}
export function inviteHighRealmStudy(s,personId,realmId){initCultivation(s);const p=requirePerson(s,personId),d=HIGH_REALM_PATHS[realmId];if(personId==='person:master'||!d||!s.srCultivation.highChapters[realmId])throw Error('须先实得续篇，向门人提供共享典籍学习机会。');if(chapterKnown(s,personId,realmId))throw Error('此人已经研习该续篇。');if(!s.homeMemberIds.includes(personId)||p.position?.sceneId!=='scene:yunxiu-courtyard'||p.realm<10)throw Error('须真实返院、筑基且能接触共享典籍。');if((p.mind?.relationships?.master?.trust??0)<45||p.mind?.caution>=85)return {accepted:false,reason:'对方暂不愿研习此高阶续篇。'};return {...startOrder(s,'high-study',{personId,realmId},{food:4},120),accepted:true};}
export function offerHighRealmMaterial(s,itemId,personId){initCultivation(s);const p=requirePerson(s,personId),i=s.itemsById[itemId],d=Object.values(HIGH_REALM_PATHS).find(d=>d.materialId===i?.definitionId);if(p.personId==='person:master'||!d||!i||i.ownerId!=='person:master'||i.location.kind!=='person'||i.location.id!=='person:master'||i.condition<=0||i.reservedBy)throw Error('须处置本人携带且未炼化/预留的具体高阶实物。');if(!shareNear(s,s.master,p)||p.activityId&&s.activitiesById[p.activityId])throw Error('双方须实际会面且有空移交。');if((p.mind?.relationships?.master?.trust??0)<45)return {accepted:false,reason:'对方不愿接受这份高阶灵材。'};const r=startOrder(s,'high-material-gift',{itemId,recipientId:personId},{},30),o=s.srCultivation.orders[r.orderId];o.helperId=personId;reserveBody(s,p,'cultivation',o.id);i.reservedBy=o.id;return {...r,accepted:true};}

