function applyHighBreakthroughPulse(s,p,o){const def=HIGH_BREAKTHROUGH_HAZARDS[o.highRealmId];if(!def||!o.refineStarted)return true;const id=`hazard:breakthrough:${o.id}`;s.hazardsById??={};const hazard=s.hazardsById[id]??={id,kind:'breakthrough-pressure',personId:p.personId,sceneId:p.position?.sceneId||'scene:yunxiu-courtyard',orderId:o.id,name:def.name,status:'active',pulses:[],energySpent:0,createdTick:s.worldTick};o.hazardId=id;for(const tick of def.pulseTicks){if(o.progressTicks<tick||hazard.pulses.some(x=>x.phaseTick===tick))continue;if(p.energy<def.energyPerPulse){o.phase='blocked';o.reason='真实'+def.name+'需精力'+def.energyPerPulse+'承受；暂停保持，取消后调息，已炼化实物不退款。';o.progressTicks=tick;return false;}p.energy-=def.energyPerPulse;hazard.pulses.push({phaseTick:tick,atTick:s.worldTick,energy:def.energyPerPulse});hazard.energySpent+=def.energyPerPulse;o.reason=def.name+'已发生第'+hazard.pulses.length+'次，保留实际精力损耗。';}return true;}

