export function beginPersonBreakthrough(s,personId='person:master',{autonomous=false}={}){if(personId!=='person:master'&&!autonomous)throw Error('门人须自主决定突破。');const v=breakthroughView(s,personId);if(v.locks.length)throw Error(v.locks.join(' '));const high=highPathForRealm(v.fromRealm),material=high&&highMaterial(s,personId,high[1]);const result=startOrder(s,'breakthrough',{fromRealm:v.fromRealm,pillCost:v.pillCost,personId},v.cost,180),o=s.srCultivation.orders[result.orderId];if(v.pillCost){o.pillAllocation=reserveAccessiblePills(s,personId,'foundation',v.pillCost,{reservationId:`pill-allocation:${o.id}`});}if(material){o.highMaterialId=material.id;o.highRealmId=high[0];material.reservedBy=o.id;}o.refineStarted=false;o.attemptId=`attempt:breakthrough:${o.id}`;return {...result,attemptId:o.attemptId};}
