export function craftPill(s,id){if(s.srWorld)return craftSR(s,id);const recipe=RECIPES[id],p=requirePerson(s);if(!recipe)throw Error('无此丹方。');if(p.realm<recipe.realm||s.sect.level<recipe.sectLevel)throw Error('炼丹资格不足。');if(recipe.knowledge&&(p.artsById?.[recipe.knowledge]?.understanding??personMind(p).knowledge?.[recipe.knowledge]??0)<recipe.mastery)throw Error('先理解可靠丹方与药理。');if(!Object.values(s.buildingsById).some(b=>b.type==='alchemy'&&b.condition>0&&b.enabled!==false))throw Error('须有实际可用丹房。');return startOrder(s,'pill-craft',{recipeId:id},recipe.cost,recipe.duration*10);}
