export function retainSoul(s,personId,informed=false){const p=requirePerson(s),target=s.personsById[personId],death=s.deathRecordsByPersonId?.[personId];if(informed!==true)throw Error('须知情：保留魂魄不复活原人物，期限与媒介代价确定。');if(!target||target.historicalOnly||!death||target.lifeStatus!=='dead'&&target.life?.status!=='dead')throw Error('只能处理刚发生且已记录的特殊死亡，不能复活父母或历史亡者。');const deathTick=death.atTick??death.deathTick;if(!Number.isSafeInteger(deathTick)||s.worldTick-deathTick>SOUL_EXTENSION.ordinaryDissipationTicks)throw Error('魂魄已经消散或历史时刻不明。');if(!corpseNear(s,p,target))throw Error('须实际到达亡者遗体近旁。');if(p.realm<16||(p.artsById?.array?.understanding??p.knowledge.array??0)<60)throw Error('须元婴以上且阵术理解60，或完整特殊环境另作内容。');if(s.srCultivation.retainedSouls[personId])throw Error('同一亡者不能重复保留魂魄。');return startOrder(s,'soul-retain',{targetPersonId:personId},SOUL_EXTENSION.retentionCost,120);}
