export function sendAvatarExplore(s,id,destination,objectId,informed=false){const a=s.srCultivation?.avatars[id],origin=requirePerson(s);if(informed!==true)throw Error('须先知情：化身实际出行可损毁，届时本体承受固定回传损耗，不代替本体调查或救人。');if(!a||a.originPersonId!==origin.personId||a.status!=='active'||a.expedition&&['outbound','walking','observing','blocked'].includes(a.expedition.phase))throw Error('没有可接受新观察任务的化身。');if(a.position?.kind!=='scene'||origin.position?.sceneId!==a.position.sceneId||!shareNear(s,origin,{...origin,position:a.position}))throw Error('出发预算须本体与化身在同一真实地点确认。');const plan=avatarRoutePlanSR(s,a.position.sceneId,destination);if(!plan.reachable)throw Error('观察通路已阻断，不能隔空投送化身。');avatarObservationPlanSR(s,destination,{x:7,y:27},objectId);const sourceStockpileId=spendResources(s,plan.cost),travelId=`travel:avatar:${id}:${s.srCultivation.nextAttempt++}`;s.travelsById[travelId]={id:travelId,avatarId:id,originPersonId:origin.personId,from:a.position.sceneId,destination,routeIds:plan.path.map(r=>r.id),durationTicks:plan.durationTicks,progressTicks:0,lastTick:s.worldTick,startedTick:s.worldTick,status:'traveling',participantIds:[],cost:structuredClone(plan.cost),sourceStockpileId};a.expedition={travelId,objectId,phase:'outbound',createdTick:s.worldTick,path:[],observationTicks:0,hazardClaims:{},reason:'化身沿真实路线自主前往，不移动本体。'};a.position={kind:'worldTravel',travelId};return {pending:true,travelId,reason:a.expedition.reason};}
export function cancelAvatarExplore(s,id){const a=s.srCultivation?.avatars[id],e=a?.expedition;if(!a||a.originPersonId!=='person:master'||a.status!=='active'||!e||!['outbound','walking','observing','blocked'].includes(e.phase))throw Error('没有可中止的实际化身观察任务。');const t=s.travelsById[e.travelId];if(a.position.kind==='worldTravel'){t.status='returned';t.destination=t.from;t.durationTicks=Math.max(1,t.progressTicks);t.progressTicks=0;t.routeIds=[];t.lastTick=s.worldTick;e.phase='returning';e.returnTicksRemaining=t.durationTicks;e.reason='沿已行路线实际返回；已付路线费用不退款。';}else{e.phase='cancelled';e.reason='就地中止查验，化身保持此地；可主动收回，不隔空发观察奖励。';}return {pending:e.phase==='returning',reason:e.reason};}
function avatarHazards(s,a){const e=a.expedition??(a.hazardLedger??={hazardClaims:{}}),p=a.position;if(p.kind!=='scene')return;for(const trap of Object.values(s.srCrises?.traps||{})){if(trap.status!=='armed'||trap.sceneId!==p.sceneId||Math.hypot(p.x-trap.x,p.y-trap.y)>2.6||e.hazardClaims[trap.id])continue;e.hazardClaims[trap.id]={atTick:s.worldTick};trap.status='triggered';trap.avatarId=a.id;damageAvatar(s,a.id,60,{sourceId:trap.id,known:false});if(a.status==='destroyed')return;}for(const c of Object.values(s.crisesById||{})){if(c.status!=='active'||!String(c.cause).includes('water')||c.sceneId!==p.sceneId||Math.hypot(p.x-c.x,p.y-c.y)>3)continue;damageAvatar(s,a.id,2,{sourceId:c.id,known:false});if(a.status==='destroyed')break;}}
function tickAvatarExpeditions(s){for(const a of Object.values(s.srCultivation.avatars)){const e=a.expedition;if(a.status!=='active'||!e||!['outbound','walking','observing','blocked','returning'].includes(e.phase))continue;const t=s.travelsById[e.travelId];if(!t){e.phase='blocked';e.reason='真实出行记录缺失，停止观察。';continue;}if(e.phase==='returning'){e.returnTicksRemaining--;t.progressTicks=Math.min(t.durationTicks,t.progressTicks+1);if(e.returnTicksRemaining<=0){a.position={kind:'scene',sceneId:t.from,x:7,y:27};e.phase='cancelled';t.status='returned';t.completedTick=s.worldTick;e.reason='已沿来路返回；本体与化身仍各有真实位置。';}continue;}if(['outbound','blocked'].includes(e.phase)&&a.position.kind==='worldTravel'){if(t.routeIds.some(id=>s.routesById[id]?.condition==='blocked')){t.status='blocked';e.phase='blocked';e.reason='实际道路阻断，化身等待或沿已走来路取消返回。';continue;}t.status='traveling';e.phase='outbound';t.progressTicks=Math.min(t.durationTicks,t.progressTicks+1);t.lastTick=s.worldTick;if(t.progressTicks<t.durationTicks)continue;t.status='arrived';t.completedTick=s.worldTick;a.position={kind:'scene',sceneId:t.destination,x:7,y:27};try{const plan=avatarObservationPlanSR(s,t.destination,a.position,e.objectId);e.path=plan.path;e.object=plan.object;e.phase='walking';e.reason='化身已抵达，沿真实可通行路径走近'+plan.object.name+'。';}catch(err){e.phase='blocked';e.reason=err.message;}continue;}if(e.phase==='walking'){let remaining=.2;while(e.path.length&&remaining>0){const n=e.path[0],d=Math.hypot(n.x-a.position.x,n.y-a.position.y);if(d<=remaining){a.position.x=n.x;a.position.y=n.y;e.path.shift();remaining-=d;}else{a.position.x+=(n.x-a.position.x)*remaining/d;a.position.y+=(n.y-a.position.y)*remaining/d;remaining=0;}}avatarHazards(s,a);if(a.status==='destroyed'){t.status='interrupted';e.phase='destroyed';e.reason='化身在实际现场损毁；本体回传按固定时限发生。';continue;}if(!e.path.length){e.phase='observing';e.reason='实际查验公开物件，需60世界步；不读取人物隐秘。';}continue;}if(e.phase==='observing'){avatarHazards(s,a);if(a.status==='destroyed'){t.status='interrupted';e.phase='destroyed';continue;}e.observationTicks++;if(e.observationTicks<60)continue;e.phase='completed';e.completedTick=s.worldTick;e.reason='化身完成现场有限观察，未改变原人物知情或发出奖励。';const fact=recordFactSR(s,`fact:avatar-observation:${e.travelId}`,{kind:'avatar-observation',originPersonId:a.originPersonId,avatarId:a.id,sceneId:a.position.sceneId,objectId:e.objectId,position:structuredClone(a.position),text:'化身沿真实道路抵达'+WORLD_SCENES[a.position.sceneId].name+'，查见'+e.object.name+'的公开现场；未确认其隐藏含义或人物实时生死。'});publishFactSR(s,fact.id);}}}

export function damageAvatar(s,id,amount,{sourceId='environment',known=true}={}){const a=s.srCultivation.avatars[id];if(!a||!['active','returning'].includes(a.status)||!Number.isFinite(amount)||amount<=0)throw Error('化身伤害目标或数值无效。');a.hp=Math.max(0,a.hp-amount);a.lastDamage={sourceId,known,atTick:s.worldTick,amount};if(a.hp===0){if(a.expedition){a.expedition.phase='destroyed';a.expedition.reason='化身损毁，停止实际观察与奖励。';const t=s.travelsById?.[a.expedition.travelId];if(t)t.status='interrupted';}a.status='destroyed';a.destroyedTick=s.worldTick;a.feedbackAtTick=s.worldTick+SOUL_EXTENSION.avatar.feedbackDelayTicks;a.feedbackApplied=false;}return {status:a.status,hp:a.hp};}
export function cancelCultivationOrder(s,id){const o=s.srCultivation?.orders[id];if(!o||['completed','cancelled'].includes(o.phase))throw Error('没有可中止修行。');if(o.highMaterialId||o.kind==='high-material-gift'){const material=s.itemsById[o.highMaterialId||o.parameters.itemId];if(material?.reservedBy===o.id)delete material.reservedBy;}if(o.materialSourceReserved){s.srCultivation.highMaterialSources[o.parameters.realmId].remaining++;o.materialSourceReserved=false;}if(!o.consumed){if(o.sourceCosts){for(const [source,cost]of Object.entries(o.sourceCosts))refundResources(s,cost,source);}else refundResources(s,o.cost,o.sourceStockpileId);if(o.pillAllocation)o.pillAllocation=refundPillAllocation(s,o.pillAllocation);}if(o.hazardId&&s.hazardsById[o.hazardId]){s.hazardsById[o.hazardId].status='interrupted';s.hazardsById[o.hazardId].interruptedTick=s.worldTick;}o.phase='cancelled';o.reason=o.consumed?'已炼化材料保留消耗，可调息后用新材料重新准备。':'预留材料与丹药已退回。';releaseSRBody(s,s.personsById[o.personId]);if(o.helperId)releaseSRBody(s,s.personsById[o.helperId]);return {refunded:!o.consumed};}
function awardStudy(s,p,id,ceiling=100){const d=TECHNIQUES[id],m=personMind(p);const a=p.artsById[id]??={artId:id,access:true,understanding:0,mastery:0,source:'actual-study',chapter:id==='foundation'?'foundation':'qi'};a.understanding=Math.max(a.understanding,Math.min(ceiling,a.understanding+12));m.knowledge[id]=Math.max(m.knowledge[id]||0,a.understanding);if(!m.main&&d.kind==='main')m.main=id;}
export function recordArtPractice(s,personId,artId,{eventId,difficulty=1,effective=true}={}){const p=requirePerson(s,personId),a=p.artsById?.[artId];if(!a||!TECHNIQUES[artId])return {accepted:false,reason:'未学得此法。'};if(!eventId||typeof eventId!=='string'||!effective||!Number.isFinite(difficulty)||difficulty<.5)return {accepted:false,reason:'无有效实践；空气练习或自伤不计。'};const key=`${personId}/${artId}/${eventId}`;if(s.srCultivation.practiceLedger[key])return {accepted:false,reason:'同一实践已结算。'};const n=Object.keys(s.srCultivation.practiceLedger).filter(k=>k.startsWith(`${personId}/${artId}/`)).length;const gain=n>=20&&difficulty<1?0:Math.min(5,difficulty*2);s.srCultivation.practiceLedger[key]={gain,atTick:s.worldTick};a.mastery=Math.min(100,a.mastery+gain);return {accepted:true,gain};}
export function teachingQualificationSR(s,personId='person:master',artId){const p=s.personsById[personId],a=p?.artsById?.[artId],d=TECHNIQUES[artId];const understanding=a?.understanding??0,mastery=a?.mastery??0;let reason='';if(!p||!isLivingPerson(p))reason='人物已离世，不能继续授艺。';else if(!d||p.realm<d.realm)reason='尚未达到典籍准入境界。';else if(understanding<65||mastery<60)reason='理解65且实际熟练60才能可靠授业。';else if(p.wound>0||p.energy<20)reason='须先实际养伤调息。';return {qualified:!reason,reason,understanding,mastery,artId};}
export function prepareLectureSR(s,artId){initCultivation(s);const master=requirePerson(s),candidates=Object.keys(master.artsById||{}).filter(id=>teachingQualificationSR(s,master.personId,id).qualified);const selected=artId||candidates.find(id=>id===personMind(master).main)||candidates[0];const view=teachingQualificationSR(s,master.personId,selected);if(!view.qualified)throw Error(view.reason);if(s.combat?.status==='active'||master.journey||personMind(master).away||master.position?.sceneId&&master.position.sceneId!=='scene:yunxiu-courtyard')throw Error('须结束山外行程并真实返院讲法。');if(master.activityId&&s.activitiesById[master.activityId]&&!['facility'].includes(s.activitiesById[master.activityId].kind))throw Error('须先完成当前身体活动。');return {artId:selected,reason:'合格讲法机会；学生依自身意愿与真实讲法工位参加。'};}
